%dw 2.0
output application/json
---
{
  error: {
    code: "RATE_PLAN_NOT_FOUND",
    message: error.description default "No rate plan matched the request",
    layer: "system-legacy-rates-soap-api",
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
  }
}

%dw 2.0
output application/json
---
